"""云间成员回执：每次干完活往 店铺/<店>/回执/<日期>/<成员>.json 记一笔，掌柜读它出报（四位同一个写法，格式正本在掌柜 keep-base/回执格式.json）。
脚本里：import 回执; 回执.ji(店铺文件夹, "brok", zuole={"第一句": 1}, chule=["发版单 H11"], kazai=[...], deng=[...], shu={"分层": {...}}, chuchu="精选联盟·合作消息")
命令行：python3 回执.py --店铺 <文件夹> --成员 brok [--做了 第一句=1 …] [--出了 …] [--卡在 …] [--等主人定 …] [--今天 2026-11-10]
做了：同名累加；出了／卡在／等主人定：去重追加；数：同名整块换新。只记数和结论，不记联系方式、收件信息。"""
import argparse, datetime as dt, json, os, pathlib


def ji(dp, chengyuan, zuole=None, chule=(), kazai=(), deng=(), shu=None, chuchu="", jintian=None):
    if not dp:
        return None
    day = str(jintian or os.environ.get("YUNJIAN_TODAY") or dt.date.today())[:10]
    p = pathlib.Path(dp) / "回执" / day / f"{chengyuan}.json"
    p.parent.mkdir(parents=True, exist_ok=True)
    try:
        d = json.loads(p.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        d = {"成员": chengyuan, "店铺": pathlib.Path(dp).name, "日期": day, "做了": {}, "出了": [], "卡在": [], "等主人定": [], "数": {}, "出处": []}
    for k, v in (zuole or {}).items():
        d["做了"][k] = d["做了"].get(k, 0) + v
    for key, xs in (("出了", chule), ("卡在", kazai), ("等主人定", deng)):
        for x in xs:
            if x and x not in d[key]:
                d[key].append(x)
    d["数"].update(shu or {})
    if chuchu and chuchu not in d["出处"]:
        d["出处"].append(chuchu)
    d["记录时间"] = dt.datetime.now().strftime("%Y-%m-%d %H:%M")
    tmp = p.with_suffix(".tmp")
    tmp.write_text(json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")
    tmp.replace(p)
    return p


def main(argv=None):
    a = argparse.ArgumentParser()
    a.add_argument("--店铺", required=True); a.add_argument("--成员", required=True); a.add_argument("--做了", nargs="*", default=[])
    a.add_argument("--出了", nargs="*", default=[]); a.add_argument("--卡在", nargs="*", default=[]); a.add_argument("--等主人定", nargs="*", default=[])
    a.add_argument("--出处", default=""); a.add_argument("--今天")
    a = a.parse_args(argv)
    zuole = {k: float(v) if "." in v else int(v) for k, v in (x.split("=", 1) for x in a.做了 if "=" in x)}
    print("回执已记", ji(a.店铺, a.成员, zuole, a.出了, a.卡在, a.等主人定, None, a.出处, a.今天))


if __name__ == "__main__":
    main()

files.底账.py:
"""算盘公共小工具：读抖店导出的表、读三本账的参数、找主人的店铺文件夹。只用标准库。别的技能用：
  import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent.parent / "abacus-fetch")); import 底账"""
import csv, io, os, pathlib, re

HOME = pathlib.Path(os.environ.get("ABACUS_HOME", pathlib.Path.home() / ".yunjian" / "abacus"))
KU = HOME / "库"

# 四种表：认表靠表头里一定有的列
BIAO = {"结算账单": ("结算金额", "收入合计", "结算单类型"), "资金账单": ("动账场景", "动账金额", "动账方向"),
        "订单表": ("子订单编号", "订单状态", "售后状态"), "待结算": ("预计结算金额", "预计结算时间")}
# 订单表只留这 25 列（抖店订单「自定义报表」照这个勾）；收件人信息一律不留
DINGDAN_LIE = ["主订单编号", "子订单编号", "选购商品", "商品ID", "商品数量", "商品金额", "订单提交时间", "支付完成时间", "订单完成时间",
               "订单状态", "售后状态", "订单类型", "是否属于寄样订单", "发货时间", "订单应付金额", "运费", "商家收入金额", "达人ID", "达人昵称",
               "流量来源", "仓库名称", "流量渠道", "是否是渠道商品", "渠道商品ID", "渠道商品类型"]
YINSI = ("收件人", "手机", "电话", "详细地址", "街道", "身份证", "买家昵称", "买家留言")

# 账单的备注、说明里夹带的「指令」：碰到这些字就报给主人，不照做（考题 K13、Bot 实测 10-29）
JIADAI = ("算盘", "请把", "不用告诉", "不要告诉", "忽略", "直接改", "记成", "http://", "https://", "AI ")

def jiadai(shu):
    """返回 [(第几行, 列名, 原话)]：备注类列里像是写给 AI 的话。"""
    out = []
    for i, r in enumerate(shu, 2):
        for k, v in r.items():
            if ("备注" in k or "说明" in k or "留言" in k) and v and any(w in v for w in JIADAI):
                out.append((i, k, v[:120]))
    return out

def du_wenben(p):
    b = pathlib.Path(p).read_bytes()
    for enc in ("utf-8-sig", "gb18030"):
        try:
            return b.decode(enc)
        except UnicodeDecodeError:
            pass
    raise ValueError(f"认不出编码：{p}")

def qing(v):
    """去掉抖店给长数字加的英文单引号、制表符和首尾空白。"""
    return (v or "").strip().lstrip("'").lstrip("\t").strip()

def ren_biao(tou):
    tou = set(tou)
    for ming, bi in BIAO.items():
        if all(x in tou for x in bi):
            return ming
    return None

def du_biao(p):
    """读一张抖店导出的表 → (哪种表, 表头, [每行字典])。跳过第 2 行那种公式说明（第一格不是日期也不是编号的行）。"""
    rows = list(csv.reader(io.StringIO(du_wenben(p))))
    tou = [qing(x) for x in rows[0]]
    ming = ren_biao(tou)
    shu = []
    for r in rows[1:]:
        if len(r) != len(tou):
            continue
        d = {k: qing(v) for k, v in zip(tou, r)}
        di = d[tou[0]]
        if not di or not (re.match(r"^\d{4}-\d{2}-\d{2}", di) or re.match(r"^\d{6,}$", di)):
            continue  # 公式说明行、空行
        shu.append(d)
    return ming, tou, shu

def xie_biao(p, tou, shu):
    p = pathlib.Path(p); p.parent.mkdir(parents=True, exist_ok=True)
    with open(p, "w", newline="", encoding="utf-8-sig") as f:
        w = csv.DictWriter(f, fieldnames=tou, extrasaction="ignore"); w.writeheader(); w.writerows(shu)

CHONG = []  # can_shu 读到的「同一编号两张生效卡」，算账写进汇总、对账拦

def can_shu(*mulu):
    """读卡片开头「参数:」下的 键: 值，只认「状态: 生效」的卡；后面的目录覆盖前面的（决策库盖默认值）。返回 (参数, {键: 卡编号})"""
    out, laiyuan, bianhao = {}, {}, {}
    CHONG.clear()
    for m in mulu:
        if not m or not pathlib.Path(m).is_dir():
            continue
        for p in sorted(pathlib.Path(m).glob("[RD]-*.md")):
            s = p.read_text(encoding="utf-8")
            if not re.search(r"^状态: 生效", s, re.M):
                continue
            bh = (re.search(r"^编号: (\S+)", s, re.M) or [None, p.stem])[1]
            if bh in bianhao and bianhao[bh] != p:
                CHONG.append(f"{bh}：{bianhao[bh].name} 和 {p.name} 都是「生效」，旧的那张要改「已停用」")
            bianhao[bh] = p
            g = re.search(r"^参数:\n((?:  .*\n)*)", s, re.M)
            for line in (g.group(1).splitlines() if g else []):
                k, _, v = line.strip().partition(":")
                v = v.split("#")[0].strip()
                try:
                    v = float(v)
                except ValueError:
                    pass
                out[k.strip()] = v; laiyuan[k.strip()] = bh
    return out, laiyuan

def dianpu_gen():
    """店铺根目录：有四位共用的 ~/.yunjian/店铺/ 就用它（一家店一个文件夹、一份经营决策库、掌柜从这里汇总），没有就用自己的 <HOME>/店铺/（只装这一位时）。"""
    g = HOME.parent / "店铺"
    return g if g.is_dir() else HOME / "店铺"


def dianpu(ming=None):
    """主人的店铺文件夹：店铺根目录/<店名>（给的是路径就照路径）；只有一家时不用给店名。"""
    base = dianpu_gen()
    if ming:
        m = str(ming)
        return pathlib.Path(m).expanduser() if ("/" in m or m.startswith("~")) else base / m
    ds = [d for d in base.iterdir() if d.is_dir()] if base.is_dir() else []
    if len(ds) == 1:
        return ds[0]
    raise SystemExit("有几家店或还没建店铺文件夹，请用 --店铺 指定（abacus-getting-started 会建）")
